//! 用户/进程 PATH 管理 + 启动期预热 (纯移动)。

use std::path::PathBuf;
use std::process::{Command, Stdio};
use std::time::Duration;

use super::probe::*;
use super::types::*;
use crate::runtime::procs::no_window;

// ───────────────────────── 用户 PATH (Windows) ─────────────────────────

/// 读「用户级 PATH」(注册表 HKCU\Environment), 经 PowerShell .NET API 拿。
#[cfg(windows)]
pub(crate) fn read_user_path() -> Option<String> {
    let mut cmd = Command::new("powershell");
    cmd.args([
        "-NoProfile",
        "-NonInteractive",
        "-Command",
        "[Environment]::GetEnvironmentVariable('Path','User')",
    ]);
    cmd.stdin(Stdio::null());
    no_window(&mut cmd);
    let out = output_with_timeout(cmd, Duration::from_secs(20))?;
    if !out.status.success() {
        return None;
    }
    Some(String::from_utf8_lossy(&out.stdout).trim().to_string())
}

#[cfg(not(windows))]
pub(crate) fn read_user_path() -> Option<String> {
    None
}

/// 读「机器级 PATH」(注册表 HKLM\...\Environment)。新开终端拿到的 PATH ≈ 机器级 + 用户级,
/// 深度校验要用它复现「用户在 CMD/PowerShell 里敲 claude」的真实解析环境 —— 本进程 PATH
/// 早被启动预热 (prime_path_for_claude) 改过, 拿它去测终端等于自欺。
#[cfg(windows)]
pub(crate) fn read_machine_path() -> Option<String> {
    let mut cmd = Command::new("powershell");
    cmd.args([
        "-NoProfile",
        "-NonInteractive",
        "-Command",
        "[Environment]::GetEnvironmentVariable('Path','Machine')",
    ]);
    cmd.stdin(Stdio::null());
    no_window(&mut cmd);
    let out = output_with_timeout(cmd, Duration::from_secs(20))?;
    if !out.status.success() {
        return None;
    }
    Some(String::from_utf8_lossy(&out.stdout).trim().to_string())
}

/// dir 是否(忽略大小写/尾斜杠)出现在分号分隔的 PATH 串里。
pub(crate) fn path_contains_dir(path_str: &str, dir: &str) -> bool {
    let norm = |s: &str| s.trim().trim_end_matches(['\\', '/']).to_lowercase();
    let target = norm(dir);
    if target.is_empty() {
        return false;
    }
    path_str.split(if cfg!(windows) { ';' } else { ':' }).any(|p| norm(p) == target)
}

/// 把 dir 前插进**当前进程 PATH** (若尚不在其中)。仅改本进程、不碰注册表; 返回是否真加了。
/// 这是「装完 / 启动后不重启即可 spawn claude」的底座 —— 子进程继承本进程 env。
pub(crate) fn prepend_process_path(dir: &str) -> bool {
    let dir = dir.trim();
    if dir.is_empty() {
        return false;
    }
    let proc_path = std::env::var("PATH").unwrap_or_default();
    if path_contains_dir(&proc_path, dir) {
        return false;
    }
    let sep = if cfg!(windows) { ';' } else { ':' };
    let new = if proc_path.is_empty() {
        dir.to_string()
    } else {
        format!("{dir}{sep}{proc_path}")
    };
    std::env::set_var("PATH", new);
    true
}

/// 把 dir 追加进「用户 PATH」(持久化, 注册表) + 当前进程 PATH (立即生效)。
/// Windows 专属; 其余平台仅尝试改进程 PATH。
pub(crate) fn ensure_dir_on_path(dir: &str) -> PathFixResult {
    let dir = dir.trim();
    if dir.is_empty() || !PathBuf::from(dir).exists() {
        return PathFixResult {
            ok: false,
            dir: Some(dir.to_string()),
            status: "skipped".into(),
            message: "目标目录不存在, 无法加入 PATH (请先安装)。".into(),
        };
    }

    // ① 当前进程 PATH (prepend → 本次会话立即能 spawn claude, 无需重启 app)
    prepend_process_path(dir);

    // ② 用户级持久化 PATH (Windows)。用显式 return 收尾, 避免 cfg 块尾表达式歧义。
    #[cfg(windows)]
    {
        if let Some(user_path) = read_user_path() {
            if path_contains_dir(&user_path, dir) {
                return PathFixResult {
                    ok: true,
                    dir: Some(dir.to_string()),
                    status: "present".into(),
                    message: format!("{dir} 已在用户 PATH 中 (进程 PATH 也已同步)。"),
                };
            }
        }
        return match append_user_path(dir) {
            Ok(_) => PathFixResult {
                ok: true,
                dir: Some(dir.to_string()),
                status: "added".into(),
                message: format!(
                    "已把 {dir} 加入用户 PATH 并同步到当前进程。新开的终端 / 重启后均生效。"
                ),
            },
            Err(e) => PathFixResult {
                ok: false,
                dir: Some(dir.to_string()),
                status: "process_only".into(),
                message: format!(
                    "已加入当前进程 PATH, 但持久化到用户 PATH 失败: {e}。可手动把 {dir} 加到 PATH。"
                ),
            },
        };
    }
    #[cfg(not(windows))]
    {
        return persist_unix_path(dir);
    }
}

/// 类 Unix(含 macOS) 持久化 PATH: 把 `export PATH="dir:$PATH"` 追加进 shell 配置
/// (zsh 为 macOS 默认, 同时照顾 bash/sh), 已存在则跳过。进程 PATH 已在调用处 prepend。
#[cfg(not(windows))]
fn persist_unix_path(dir: &str) -> PathFixResult {
    use std::io::Write;
    let home = match home_dir() {
        Some(h) => h,
        None => {
            return PathFixResult {
                ok: true,
                dir: Some(dir.to_string()),
                status: "process_only".into(),
                message: format!("已加入当前进程 PATH ({dir})。"),
            }
        }
    };
    let line = format!("export PATH=\"{dir}:$PATH\"");
    let mut wrote = false;
    let mut already = false;
    for rc in [".zshrc", ".zprofile", ".bash_profile", ".profile"] {
        let p = home.join(rc);
        let existing = std::fs::read_to_string(&p).unwrap_or_default();
        if existing.contains(dir) {
            already = true;
            continue;
        }
        if let Ok(mut f) = std::fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(&p)
        {
            let _ = writeln!(f, "\n# Added by Polaris\n{line}");
            wrote = true;
        }
    }
    if wrote {
        PathFixResult {
            ok: true,
            dir: Some(dir.to_string()),
            status: "added".into(),
            message: format!(
                "已把 {dir} 写进 shell 配置 (~/.zshrc 等) 并同步当前进程。新开终端即生效。"
            ),
        }
    } else if already {
        PathFixResult {
            ok: true,
            dir: Some(dir.to_string()),
            status: "present".into(),
            message: format!("{dir} 已在 shell 配置中 (进程 PATH 已同步)。"),
        }
    } else {
        PathFixResult {
            ok: true,
            dir: Some(dir.to_string()),
            status: "process_only".into(),
            message: format!("已加入当前进程 PATH ({dir})。"),
        }
    }
}

/// 通过 PowerShell .NET API 把 dir 追加进用户 PATH (会广播 WM_SETTINGCHANGE)。
#[cfg(windows)]
fn append_user_path(dir: &str) -> Result<(), String> {
    // 单引号转义: PowerShell 里单引号字符串内的 ' 写成 ''
    let safe = dir.replace('\'', "''");
    let script = format!(
        "$d = '{safe}'; \
$u = [Environment]::GetEnvironmentVariable('Path','User'); \
if ($null -eq $u) {{ $u = '' }}; \
$parts = $u.Split(';') | Where-Object {{ $_ -ne '' }}; \
if ($parts -notcontains $d) {{ \
  $base = $u.TrimEnd(';'); \
  if ($base -eq '') {{ $new = $d }} else {{ $new = $base + ';' + $d }}; \
  [Environment]::SetEnvironmentVariable('Path', $new, 'User'); \
  Write-Output 'ADDED' \
}} else {{ Write-Output 'PRESENT' }}"
    );
    let mut cmd = Command::new("powershell");
    cmd.args(["-NoProfile", "-NonInteractive", "-Command", &script]);
    cmd.stdin(Stdio::null());
    no_window(&mut cmd);
    let out = cmd
        .output()
        .map_err(|e| format!("调用 PowerShell 写 PATH 失败: {e}"))?;
    if out.status.success() {
        Ok(())
    } else {
        Err(String::from_utf8_lossy(&out.stderr).trim().to_string())
    }
}

/// 把 uv (与随包内置的 Python) 目录并进**本进程** PATH。
/// 内置那份放在用户自装之后 —— 用户装过就用他的, 没装才吃内置的。
/// 这里只上 uv/python(不会与系统命令重名), msys 的 unix 工具目录**不上进程 PATH**
/// (它有 find/sort 等与 System32 同名的 exe), 那批只前插进 claude 子进程,
/// 见 `doctor::probe::inject_bundled_runtime`。
pub fn ensure_uv_on_process_path() {
    if let Some(dir) = uv_bin_dir() {
        if dir.join(uv_exe_name()).exists() {
            prepend_process_path(&dir.to_string_lossy());
        }
    }
    for dir in [super::bundled::uv_dir(), super::bundled::python_dir()]
        .into_iter()
        .flatten()
    {
        prepend_process_path(&dir.to_string_lossy());
    }
}

/// 由一个具体的 claude 可执行文件路径推出「该上 PATH 的目录」。
/// npm 装解析到的常是 `node_modules/.../bin/claude.exe` —— 该上 PATH 的是 npm 全局前缀
/// (放 `claude.cmd` 的地方, npm 通常已替我们加好), 而非内部 bin 目录; 其余情况取父目录。
pub(crate) fn claude_dir_from_path(p: &std::path::Path) -> Option<PathBuf> {
    if p.components().any(|c| c.as_os_str() == "node_modules") {
        if let Some(prefix) = npm_global_prefix() {
            return Some(prefix);
        }
    }
    p.parent().map(|x| x.to_path_buf())
}

/// claude 应该落脚的目录 (用于「修复 PATH」): 已解析路径的父目录优先, 否则 ~/.local/bin。
pub(crate) fn claude_dir_for_fix(claude: &ToolStatus) -> Option<PathBuf> {
    if let Some(p) = &claude.path {
        let pb = PathBuf::from(p.replace('/', std::path::MAIN_SEPARATOR_STR));
        return claude_dir_from_path(&pb);
    }
    home_dir().map(|h| h.join(".local").join("bin"))
}

/// 装完 PowerShell 7 后, 把它的目录 (`C:\Program Files\PowerShell\7`) 塞进 PATH (进程 + 用户),
/// 让**本进程**后续 spawn 的 claude 立刻找到真身, 而不是 WindowsApps 里起不来的 Store 别名 —— 装完免重启即用。
/// 真身不存在 (没装成功) 时返回 None。
pub(crate) fn ensure_pwsh_on_path() -> Option<PathFixResult> {
    let exe = pwsh_candidates().into_iter().find(|p| p.exists())?;
    let dir = exe.parent()?.to_string_lossy().to_string();
    Some(ensure_dir_on_path(&dir))
}

/// 启动期环境预热 —— 让本进程**之后** spawn 的 claude CLI 一定「找得到、且有 shell 可用」,
/// 不必等用户走一遍「环境医生 / 安装」, 也不必重启 app。对应「环境配置时把 PATH 改成适合
/// claude code CLI 调用, 避免类似(找不到 claude / 找不到 shell)的问题」。
///
/// 只改**当前进程** env (set_var), **不写注册表** —— 启动期保持轻量、幂等、无副作用;
/// 持久化仍由「安装成功」与显式「修复 PATH」按钮负责。三件事, 每件仅在尚未满足时才动:
/// ① claude 所在目录 → 进程 PATH (即便 app 从一个 PATH 不含它的上下文被拉起也能裸名命中);
/// ② 真身 PowerShell 7 目录 → 进程 PATH (claude 在 Windows 靠 pwsh/git-bash 跑工具, 缺则报错);
/// ③ 找到 Git Bash 就设 `CLAUDE_CODE_GIT_BASH_PATH` (claude 在 Windows 默认偏好 git-bash)。
///
/// 内部会跑 where.exe / `npm prefix -g` (可能各几百 ms), 故在后台线程里做, 不阻塞 app 启动。
pub fn prime_path_for_claude() {
    std::thread::spawn(prime_path_for_claude_inner);
}

/// macOS/Linux: 从 Finder/Dock 启动的 GUI 进程只继承极简 PATH (`/usr/bin:/bin:/usr/sbin:/sbin`),
/// 拿不到用户 shell (`~/.zprofile`/`~/.profile` 里 —— 我们装 Node 时及 Homebrew 都写在这) 配的
/// node/npm/claude 目录 → `which`/spawn 全落空。跑一次**登录 shell** 把真实 PATH 取回来。
/// 用 `-lc`(登录、非交互): 读 `.zprofile`/`.profile`/`.bash_profile`, 不读 `.zshrc`, 既能拿到
/// 我们写的 node 目录与 Homebrew, 又避开交互式 shell 无 tty 时可能的卡顿。
#[cfg(not(windows))]
fn login_shell_path() -> Option<String> {
    let shell = std::env::var("SHELL").unwrap_or_else(|_| "/bin/zsh".to_string());
    let mut cmd = Command::new(&shell);
    cmd.args(["-lc", "printf %s \"$PATH\""]);
    cmd.stdin(Stdio::null());
    let out = output_with_timeout(cmd, Duration::from_secs(20))?;
    if !out.status.success() {
        return None;
    }
    let p = String::from_utf8_lossy(&out.stdout).trim().to_string();
    if p.is_empty() {
        None
    } else {
        Some(p)
    }
}

/// 把登录 shell 的 PATH 里「进程 PATH 还没有的目录」并到进程 PATH 末尾 (系统目录仍优先,
/// 仅补充用户目录, 不抢占)。让本进程之后 `which`/spawn 与终端里行为一致。
#[cfg(not(windows))]
fn merge_login_path_into_process(login_path: &str) {
    use std::collections::HashSet;
    let cur = std::env::var("PATH").unwrap_or_default();
    let have: HashSet<String> = cur
        .split(':')
        .map(|s| s.trim_end_matches('/').to_string())
        .collect();
    let adds: Vec<&str> = login_path
        .split(':')
        .filter(|s| !s.is_empty() && !have.contains(&s.trim_end_matches('/').to_string()))
        .collect();
    if adds.is_empty() {
        return;
    }
    let merged = if cur.is_empty() {
        adds.join(":")
    } else {
        format!("{cur}:{}", adds.join(":"))
    };
    std::env::set_var("PATH", merged);
}

/// 预热的实际逻辑 (同步)。抽出来便于单测直接调用并断言, 公开入口只负责丢到后台线程。
pub(crate) fn prime_path_for_claude_inner() {
    // ⓪ macOS/Linux: 先并入登录 shell 的真实 PATH (Finder 启动只有极简 PATH), 再直接补上
    // 本应用装 Node 的目录 —— 即便 shell 配置因故没生效, node/npm/claude 也都找得到。
    #[cfg(not(windows))]
    {
        if let Some(lp) = login_shell_path() {
            merge_login_path_into_process(&lp);
        }
        for dir in node_dir_candidates() {
            if dir.exists() {
                prepend_process_path(&dir.to_string_lossy());
            }
        }
    }
    // ⓪.5 Windows: PATH 里找不到 node 时, 把 Node 安装目录补进**进程** PATH。
    // MSI/winget 只写注册表 PATH, **运行中的进程 PATH 是启动时的快照、不会刷新** → 用户在 app
    // 开着的时候装完 Node, 面板仍说没有 npm、更新检测也拿不到 npm。仅在 PATH 确实解析不出 node
    // 时才补, 不抢占用户自己配的 node (nvm 等多版本管理器)。
    #[cfg(windows)]
    if which_all("node").is_empty() {
        if let Some(dir) = node_dir_candidates()
            .into_iter()
            .find(|d| d.join("node.exe").exists())
        {
            prepend_process_path(&dir.to_string_lossy());
        }
    }
    // ① claude 目录上进程 PATH
    if let Some(exe) = resolve_claude_exe() {
        if let Some(dir) = claude_dir_from_path(&exe) {
            prepend_process_path(&dir.to_string_lossy());
        }
    }
    // ①.5 uv 目录上进程 PATH —— 脚本执行公约要求 claude 用 `uv run` 跑 Python, 它的 shell 得找得到 uv
    ensure_uv_on_process_path();
    // ② 真身 pwsh 目录上进程 PATH (滤掉 Store 别名: pwsh_candidates 只列 Program Files 真身)
    #[cfg(windows)]
    if let Some(exe) = pwsh_candidates().into_iter().find(|p| p.exists()) {
        if let Some(dir) = exe.parent() {
            prepend_process_path(&dir.to_string_lossy());
        }
    }
    // ③ Git Bash → 环境变量 (用户没显式设过才补)
    #[cfg(windows)]
    if std::env::var_os("CLAUDE_CODE_GIT_BASH_PATH").is_none() {
        if let Some(bash) = git_bash_path() {
            std::env::set_var("CLAUDE_CODE_GIT_BASH_PATH", bash);
        }
    }
}

#[cfg(test)]
#[path = "path_tests.rs"]
mod tests;
//! 探测原语: which/版本探测、候选路径、工具检测、claude/uv 解析、子进程环境净化 (纯移动)。

use parking_lot::Mutex;
use std::path::PathBuf;
use std::process::{Command, Stdio};
use std::time::{Duration, Instant};

use super::types::*;
use crate::runtime::procs::no_window;

#[path = "probe_helpers.rs"]
mod helpers;
pub(crate) use helpers::*;

/// chat.rs spawn 用的解析结果缓存 —— 避免每次发消息都跑 `where.exe` / `npm prefix -g`。
/// 安装成功后 (`stream_install`) 会清空, 下次重新解析。
pub(crate) static CLAUDE_EXE_CACHE: once_cell::sync::Lazy<Mutex<Option<PathBuf>>> =
    once_cell::sync::Lazy::new(|| Mutex::new(None));

/// 子进程环境净化（借鉴 OpenCode 桌面端 sidecar：loopback 强制 NO_PROXY + 清干扰变量）。
/// 给将要 spawn 的 **宿主机 claude** 子进程套上两层防护：
///
/// ① **回环并进 NO_PROXY**：切到 Codex 时 claude 的 `ANTHROPIC_BASE_URL` 被指向
///    `http://127.0.0.1:{port}`（见 provider.rs 的 `codex_route_config`）。若用户配了系统级
///    `HTTP(S)_PROXY`（国内/企业网常见），claude 底层 HTTP 客户端会把这个 **loopback 请求也走代理**
///    → 连不上本地翻译代理、报「连接 ChatGPT 后端失败」。把回环列入 `NO_PROXY`/`no_proxy` 即绕开代理直连。
///    只补回环、不动其他代理设置 —— 代理本身（claude 直连远端 API 时要用）照常生效。
/// ② **清干扰继承变量**：`DEBUG`（让 Node 生态吐调试噪声、行为不可预测）；Linux 的 `LD_PRELOAD`（注入）。
/// ③ **root 下放行 bypassPermissions**：claude CLI 有条安全铁律——进程是 root(euid==0)时
///    拒绝 `--permission-mode=bypassPermissions` / `--dangerously-skip-permissions`，报
///    「cannot be used with root/sudo privileges」。但 **Docker 版容器必须跑 root**(群晖
///    bind mount 里 synoacl 失效 → 共享 000 权限 → 非 root 全读不了，见 nas-polaris-datasets-mount)，
///    一旦走到 kb.rs 硬编 bypass 的路径(文件中心 AI 归类 / KB 构建 / 回声层做梦 / fable 索引)
///    claude 必挂。官方逃生口 = 设 `IS_SANDBOX=1`，root 下即放行。仅 Linux 且确为 root 时设置，
///    桌面(非 root)不触发，无副作用。
pub fn harden_child_env(cmd: &mut Command) {
    for key in ["NO_PROXY", "no_proxy"] {
        let current = std::env::var(key).unwrap_or_default();
        cmd.env(key, merge_no_proxy(&current));
    }
    cmd.env_remove("DEBUG");
    inject_bundled_runtime(cmd);
    #[cfg(target_os = "linux")]
    {
        cmd.env_remove("LD_PRELOAD");
        // SAFETY: getuid 是纯读、线程安全的 libc 调用，无副作用。
        if unsafe { libc::geteuid() } == 0 {
            cmd.env("IS_SANDBOX", "1");
        }
    }
}

/// 把随安装包内置的运行时 (uv / Python / Git Bash) 喂给 **claude 子进程**:
/// ① `CLAUDE_CODE_GIT_BASH_PATH` 指向可用的 bash (用户自装的优先, 内置兜底);
/// ② 把 uv / Python 目录 —— 用内置 bash 时再加上 msys 的 `usr/bin`、`mingw64/bin` ——
///    **前插**进子进程 PATH。
///
/// 为什么必须前插 msys 目录 (2026-07-23 实测): 非登录 bash (`bash -c`) 不读 `/etc/profile`,
/// PATH 里没有 `/usr/bin` → `ls/cat/grep/sed/awk` 全部 command not found; 而 `find`/`sort`
/// 会**静默命中 System32 的同名 exe**(Windows 的 find 是查字符串、sort 是另一套语义),
/// 结果错了还不报错。前插之后 unix 工具压过 System32, bash 里的行为才与 mac/Linux 一致。
///
/// 只动子进程 env, **不碰本进程 PATH** —— 免得 msys 的同名 exe 污染整个应用。
fn inject_bundled_runtime(cmd: &mut Command) {
    // bash: 类 Unix 无此概念, 恒 false。
    #[allow(unused_mut)]
    let mut using_bundled_bash = false;
    #[cfg(windows)]
    {
        // ★ 必须**先解析出到底用哪个 bash**, 再判断它是不是内置的 —— 不能写成
        //   「环境变量没设才处理」: 启动期 prime_path_for_claude 早就把这个变量设好了,
        //   那样写的话 using_bundled_bash 永远是 false, msys 工具目录永远注入不进去。
        let bash = std::env::var_os("CLAUDE_CODE_GIT_BASH_PATH")
            .map(PathBuf::from)
            .filter(|p| p.exists())
            .or_else(git_bash_path);
        if let Some(bash) = bash {
            using_bundled_bash = super::bundled::is_bundled(&bash);
            cmd.env("CLAUDE_CODE_GIT_BASH_PATH", &bash);
        }
    }

    let prefix = super::bundled::child_path_prefix(using_bundled_bash);
    if prefix.is_empty() {
        return;
    }
    let sep = if cfg!(windows) { ';' } else { ':' };
    let current = std::env::var("PATH").unwrap_or_default();
    // 已在 PATH 里的不重复插 (幂等: 同一条 Command 上调两次结果一样)
    let mut parts: Vec<String> = prefix
        .iter()
        .map(|p| p.to_string_lossy().to_string())
        .filter(|d| !super::path::path_contains_dir(&current, d))
        .collect();
    if parts.is_empty() {
        return;
    }
    if !current.is_empty() {
        parts.push(current);
    }
    cmd.env("PATH", parts.join(&sep.to_string()));
}

/// 把回环主机（`127.0.0.1` / `localhost` / `::1`）并进既有 NO_PROXY 值：
/// 保留用户原有条目、大小写不敏感去重、已存在则不重复添加。抽纯函数便于单测。
pub fn merge_no_proxy(current: &str) -> String {
    let mut items: Vec<String> = current
        .split(',')
        .map(|s| s.trim().to_string())
        .filter(|s| !s.is_empty())
        .collect();
    for host in ["127.0.0.1", "localhost", "::1"] {
        if !items.iter().any(|v| v.eq_ignore_ascii_case(host)) {
            items.push(host.to_string());
        }
    }
    items.join(",")
}

/// 解析一个「可直接 spawn」的 claude 可执行文件全路径, 供 chat.rs 调起宿主机 CLI。
///
/// 为什么不让 chat.rs 用裸名 `Command::new("claude")`: Windows 的 `CreateProcessW` 解析裸名时
/// 只补 `.exe`、不查 PATHEXT, 而 **npm 装只在 PATH 放 `claude.cmd`** → 裸名根本找不到。
/// 这里偏好真·原生 `.exe` (PATH 命中的 .exe → 已知候选里的 .exe), 实在没有才回退到 `.cmd`;
/// 全部落空返回 None, 让调用方退回裸名靠 PATH。带进程内缓存。
pub fn resolve_claude_exe() -> Option<PathBuf> {
    // 命中缓存且文件仍在 → 直接用
    if let Some(p) = CLAUDE_EXE_CACHE.lock().as_ref() {
        if p.exists() {
            return Some(p.clone());
        }
    }
    let resolved = resolve_claude_exe_uncached();
    *CLAUDE_EXE_CACHE.lock() = resolved.clone();
    resolved
}

fn resolve_claude_exe_uncached() -> Option<PathBuf> {
    let is_exe = |p: &std::path::Path| {
        p.extension()
            .map(|e| e.eq_ignore_ascii_case("exe"))
            .unwrap_or(false)
    };
    let hits = which_all("claude"); // 已过滤为「存在的」路径
                                    // 1. PATH 命中里的 .exe (原生装常见)
    if let Some(p) = hits.iter().find(|p| is_exe(p)) {
        return Some(p.clone());
    }
    // 2. 已知候选里存在的 .exe (npm 装 → node_modules 里的原生 exe)
    let cands = claude_candidates();
    if let Some(p) = cands.iter().find(|p| is_exe(p) && p.exists()) {
        return Some(p.clone());
    }
    // 3. 退而求其次: 任意 PATH 命中 / 存在候选 (可能是 .cmd)
    hits.into_iter()
        .next()
        .or_else(|| cands.into_iter().find(|p| p.exists()))
}

pub(crate) fn pwsh_candidates() -> Vec<PathBuf> {
    vec![
        PathBuf::from(r"C:\Program Files\PowerShell\7\pwsh.exe"),
        PathBuf::from(r"C:\Program Files\PowerShell\7-preview\pwsh.exe"),
    ]
}

/// Node.js 可执行文件所在目录候选 (放 `node`/`npm`)。装完 Node 后用它把目录塞进进程 PATH,
/// 让同一会话紧接着的 npm/claude 安装立刻找得到 npm (免重启 app)。
pub(crate) fn node_dir_candidates() -> Vec<PathBuf> {
    #[cfg(windows)]
    {
        let mut v = Vec::new();
        // 后台静默安装装的**便携版 Node**(免管理员、不弹 UAC) —— 排在系统安装之前:
        // 它是本应用自己装的, 版本可控; 见 doctor::autopilot。
        if let Some(h) = home_dir() {
            v.push(h.join(".local").join("polaris-node"));
        }
        v.push(PathBuf::from(r"C:\Program Files\nodejs"));
        v.push(PathBuf::from(r"C:\Program Files (x86)\nodejs"));
        v
    }
    #[cfg(not(windows))]
    {
        let mut v = Vec::new();
        if let Some(h) = home_dir() {
            // 本应用免 sudo 装 Node 的落脚处 (见 MAC_NODE_INSTALL_SCRIPT), 优先
            v.push(h.join(".local").join("polaris-node").join("bin"));
            v.push(h.join(".local").join("bin"));
        }
        // Homebrew (Apple Silicon / Intel) 与系统常见位置
        v.push(PathBuf::from("/opt/homebrew/bin"));
        v.push(PathBuf::from("/usr/local/bin"));
        v
    }
}

/// Windows「应用执行别名」空壳: `%LOCALAPPDATA%\Microsoft\WindowsApps\` 下的 0 字节重解析点
/// (从 Microsoft Store 装 PowerShell 7 / Python 等会留下)。交互式终端里它能转发到 Store 真身,
/// 但**本应用是 GUI 进程、以 CREATE_NO_WINDOW 无控制台方式 spawn claude**, claude 再去拉这个
/// 别名时在该上下文下起不来 → 报「找不到 PowerShell」。故探测时把它当「没装」, 引导装
/// Program Files 里的真身 (普通 exe, 任何子进程都能稳定 spawn) 替代。
pub(crate) fn is_app_exec_alias(p: &std::path::Path) -> bool {
    #[cfg(windows)]
    {
        let in_windows_apps = p.components().any(|c| {
            c.as_os_str()
                .to_string_lossy()
                .eq_ignore_ascii_case("WindowsApps")
        });
        if !in_windows_apps {
            return false;
        }
        // 0 字节 = 典型的执行别名占位 (reparse point), 不是真二进制
        std::fs::metadata(p).map(|m| m.len() == 0).unwrap_or(false)
    }
    #[cfg(not(windows))]
    {
        let _ = p;
        false
    }
}

/// 探测可用的 Git Bash (claude 在 Windows 上可接受的另一种 shell)。
/// 先认 `CLAUDE_CODE_GIT_BASH_PATH` 覆盖, 再扫常见安装位置, **最后回落到随包内置的那份**。
/// 仅 Windows 需要 (扫的全是 Windows 路径); 类 Unix 用系统自带 shell, 不走这里。
///
/// 内置的排最后: 用户自己装的 Git for Windows 是完整版(工具更全、还带 `which`),
/// 有就用它; 内置的 MinGit 只保证「没装 Git 的机器也有 bash 可用」, 免得用户被迫去装
/// PowerShell 7 / Git。
#[cfg(windows)]
pub(crate) fn git_bash_path() -> Option<PathBuf> {
    if let Ok(p) = std::env::var("CLAUDE_CODE_GIT_BASH_PATH") {
        let pb = PathBuf::from(p);
        if pb.exists() {
            return Some(pb);
        }
    }
    [
        r"C:\Program Files\Git\bin\bash.exe",
        r"C:\Program Files\Git\usr\bin\bash.exe",
        r"C:\Program Files (x86)\Git\bin\bash.exe",
    ]
    .iter()
    .map(PathBuf::from)
    .find(|p| p.exists())
    .or_else(super::bundled::git_bash)
}

/// 通用工具探测: which 命中 + 已知候选, 取首个可用; on_path = 是否被 PATH 发现。
pub(crate) fn detect(
    key: &str,
    name: &str,
    bin: &str,
    version_args: &[&str],
    candidates: &[PathBuf],
    required: bool,
    install_hint: &str,
) -> ToolStatus {
    // 滤掉 WindowsApps 的执行别名空壳 —— 它对无控制台 spawn 的 claude 不可用, 不能算「已装」
    let on_path_hits: Vec<PathBuf> = which_all(bin)
        .into_iter()
        .filter(|p| !is_app_exec_alias(p))
        .collect();
    let on_path = !on_path_hits.is_empty();

    // 解析出一个具体路径: PATH 命中按「能不能直接跑」排序 (见 exec_rank), 否则用存在的候选
    let resolved: Option<PathBuf> = {
        let mut hits = on_path_hits.clone();
        hits.sort_by_key(|p| exec_rank(p)); // 稳定排序: 同级保持 where.exe 原序
        hits.into_iter()
            .next()
            .or_else(|| candidates.iter().find(|p| p.exists()).cloned())
    };

    let found = resolved.is_some();
    // 按解析出的绝对路径探版本, 裸名仅作兜底 —— 否则「装了但不在 PATH」的机器上版本恒为空,
    // 面板只显示「已安装」而没有版本号, claude 那行还会连带让更新检测失效 (见 update.rs)。
    let version = resolved
        .as_deref()
        .and_then(|p| probe_version_at(p, version_args))
        .or_else(|| found.then(|| probe_version(bin, version_args)).flatten());

    let hint = if found {
        match &version {
            Some(v) => v.clone(),
            None => "已安装".to_string(),
        }
    } else {
        install_hint.to_string()
    };

    let bundled = resolved.as_deref().is_some_and(super::bundled::is_bundled);
    ToolStatus {
        key: key.to_string(),
        name: name.to_string(),
        found,
        version,
        path: resolved.as_deref().map(to_fwd),
        on_path,
        required,
        hint,
        bundled,
    }
}

// ───────────────────────── uv 解析 ─────────────────────────

pub(crate) fn uv_bin_dir() -> Option<PathBuf> {
    home_dir().map(|h| h.join(".local").join("bin"))
}

/// uv 可执行文件名 (随平台)。
pub(crate) fn uv_exe_name() -> &'static str {
    if cfg!(windows) {
        "uv.exe"
    } else {
        "uv"
    }
}

/// 解析一个可直接 spawn 的 uv 路径: PATH 命中优先(滤掉 Store 占位符——uv 本身不是占位符,
/// 但走同一道防御闸更稳), 否则取 `~/.local/bin/uv(.exe)`。
pub(crate) fn resolve_uv_exe() -> Option<PathBuf> {
    if let Some(p) = which_all("uv").into_iter().find(|p| !is_app_exec_alias(p)) {
        return Some(p);
    }
    uv_bin_dir()
        .map(|d| d.join(uv_exe_name()))
        .filter(|p| p.exists())
        // 用户自己装的都没有 → 用随安装包内置的那份 (免安装、免管理员)
        .or_else(super::bundled::uv_exe)
}

/// uv 探测候选 (PATH 落空时按序取首个存在的): 用户自装的 `~/.local/bin` 优先, 内置兜底。
pub(crate) fn uv_candidates() -> Vec<PathBuf> {
    let mut v: Vec<PathBuf> = uv_bin_dir()
        .map(|d| vec![d.join(uv_exe_name())])
        .unwrap_or_default();
    v.extend(super::bundled::uv_exe());
    v
}

/// Python 探测候选 —— 只有内置那份。系统 Python 由 PATH 命中负责 (见 `detect`)。
pub(crate) fn python_candidates() -> Vec<PathBuf> {
    super::bundled::python_exe().into_iter().collect()
}

