import { createHash } from 'node:crypto';

export function nodeVersion(engine, override) {
  const match = /^>=(\d+\.\d+\.\d+)$/.exec(engine);
  if (!match) throw new Error(`Unsupported Node engine: ${engine}`);
  const version = override ?? match[1];
  if (!/^\d+\.\d+\.\d+$/.test(version)) throw new Error('Node version must be x.y.z');
  const a = version.split('.').map(Number), b = match[1].split('.').map(Number);
  const difference = a.map((n, i) => n - b[i]).find(n => n !== 0) ?? 0;
  if (difference < 0) throw new Error(`Node ${version} does not satisfy ${engine}`);
  return version;
}

export function nodePlan(version, platform, arch, sources = {}) {
  if (!['win32', 'darwin', 'linux'].includes(platform) || !['x64', 'arm64'].includes(arch)) {
    throw new Error(`Unsupported Node target: ${platform}/${arch}`);
  }
  const win = platform === 'win32';
  const asset = `node-v${version}-${win ? 'win' : platform}-${arch}.${win ? 'zip' : 'tar.gz'}`;
  const official = `https://nodejs.org/dist/v${version}`;
  const base = sources.deps ?? 'https://llmwiki.cloud/downloads/deps';
  const proxies = sources.proxies ?? ['https://ghfast.top', 'https://ghproxy.net'];
  for (const url of [base, ...proxies]) {
    if (new URL(url).protocol !== 'https:') throw new Error('Runtime sources must use HTTPS');
  }
  return {
    name: 'node', dir: 'node', asset, magic: win ? '504b' : '1f8b',
    minBytes: 10 * 1024 * 1024, strip: 1, check: win ? 'node.exe' : 'bin/node',
    urls: [`${base}/${asset}`, ...proxies.map(p => `${p}/${official}/${asset}`), `${official}/${asset}`],
    checksumUrl: `${official}/SHASUMS256.txt`,
  };
}

export function checksumFor(manifest, asset) {
  const matches = manifest.split(/\r?\n/).map(line => /^([a-fA-F0-9]{64})\s+\*?(\S+)$/.exec(line))
    .filter(match => match?.[2] === asset);
  if (matches.length !== 1) throw new Error(`Missing or duplicate official SHA256 for ${asset}`);
  return matches[0][1].toLowerCase();
}

export function verifySha256(bytes, expected) {
  if (!/^[a-f0-9]{64}$/.test(expected) || createHash('sha256').update(bytes).digest('hex') !== expected) {
    throw new Error('Node SHA256 mismatch');
  }
}

export function componentCurrent(have, want, name, intact) {
  return intact && have?.platform === want.platform && have?.arch === want.arch && have?.[name] === want[name];
}
import { test } from 'vitest';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { nodeVersion, nodePlan, checksumFor, verifySha256, componentCurrent } from './node.mjs';
test('Node engine minimum and explicit versions are validated', () => {
  assert.equal(nodeVersion('>=22.19.0'), '22.19.0');
  assert.equal(nodeVersion('>=22.19.0', '24.1.0'), '24.1.0');
  for (const v of ['22.18.9', '20.99.0', 'latest', '22.19.0/evil']) {
    assert.throws(() => nodeVersion('>=22.19.0', v));
  }
  assert.throws(() => nodeVersion('^22'));
});
test('official artifacts cover six supported targets and ordered mirrors', () => {
  for (const platform of ['win32', 'darwin', 'linux']) for (const arch of ['x64', 'arm64']) {
    const plan = nodePlan('22.19.0', platform, arch);
    assert.ok(plan.urls[0].includes('llmwiki.cloud'));
    assert.ok(plan.urls.at(-1).startsWith('https://nodejs.org/dist/'));
    assert.ok(plan.asset.includes(arch));
    assert.equal(plan.check, platform === 'win32' ? 'node.exe' : 'bin/node');
  }
  assert.throws(() => nodePlan('22.19.0', 'linux', 'ia32'));
});
test('checksum requires exact unique asset and rejects corruption and HTML', () => {
  const data = Buffer.from('portable node fixture');
  const hash = createHash('sha256').update(data).digest('hex');
  assert.equal(checksumFor(`${hash}  node.zip\n`, 'node.zip'), hash);
  verifySha256(data, hash);
  assert.throws(() => verifySha256(Buffer.from('<html>proxy failure'), hash));
  assert.throws(() => checksumFor(`${hash}  node.zip.old`, 'node.zip'));
  assert.throws(() => checksumFor(`${hash}  node.zip\n${hash}  node.zip`, 'node.zip'));
});
test('existing binary cannot hide a version or target change', () => {
  const want = {platform: 'win32', arch: 'x64', node: '22.19.0'};
  assert.equal(componentCurrent(want, want, 'node', true), true);
  for (const have of [undefined, {...want, node: '20.0.0'}, {...want, arch: 'arm64'}]) {
    assert.equal(componentCurrent(have, want, 'node', true), false);
  }
  assert.equal(componentCurrent(want, want, 'node', false), false);
});
import assert from "node:assert/strict";
import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { test } from "node:test";
import { createReadOnlyTools } from "@earendil-works/pi-coding-agent";
import { loadConfig, mergeConfig } from "../src/config/load.ts";
import { DaemonError, publicError } from "../src/protocol/errors.ts";
import { createSession } from "../src/sessions/create.ts";
import { harness, result } from "./helpers.ts";

test("retry and compaction defaults and overrides reach actual Pi session SettingsManager", async () => {
  const defaults = loadConfig();
  assert.equal(defaults.turnIdleTimeoutMs, 180000);
  assert.equal(defaults.turnMaxMs, 0);
  assert.equal(defaults.retry.enabled, true);
  assert.equal(defaults.compaction.enabled, true);
  const h = await harness();
  try {
    for (const retry of [defaults.retry, { enabled: true, maxRetries: 7, baseDelayMs: 123, maxAgentDelayMs: 4567 }]) {
      const config = mergeConfig(h.daemon.config, { retry });
      const session = await createSession(config, h.daemon.models, [], undefined, h.dir);
      try {
        assert.deepEqual(session.settingsManager.getRetrySettings(), retry);
        assert.equal(session.settingsManager.getCompactionEnabled(), true);
      } finally { session.dispose(); }
    }
  } finally { await h.close(); }
});

test("default allowlist matches SDK read-only tools; write/exec requires explicit host configuration", async () => {
  const tools = loadConfig().tools;
  const h = await harness([], { tools });
  try {
    assert.deepEqual(tools, createReadOnlyTools(h.dir).map((tool) => tool.name));
    const opened = result<{ sessionId: string; tools: string[] }>(await h.request("session.open", { cwd: h.dir }));
    assert.deepEqual(opened.tools, tools);
    assert.ok(!opened.tools.some((name) => ["bash", "powershell", "edit", "write"].includes(name)));
    await h.request("close", { sessionId: opened.sessionId });
    await h.request("config.apply", { config: { tools: ["read", "bash", "edit", "write"] } });
    const explicit = result<{ tools: string[] }>(await h.request("session.open", { cwd: h.dir }));
    assert.deepEqual(explicit.tools, ["read", "bash", "edit", "write"]);
  } finally { await h.close(); }
});

test("file and runtime validation return only failing JSON Pointer paths, preserving all nested errors", async () => {
  const h = await harness();
  try {
    const invalid = { maxSessions: 0, retry: { enabled: "private-retry", baseDelayMs: "private-delay" },
      providers: [{ ...h.daemon.config.providers[0], baseUrl: 42 }], unexpected: "private-extra" };
    const expected = ["/maxSessions", "/providers/0/baseUrl", "/retry/baseDelayMs", "/retry/enabled", "/unexpected"];
    const response = await h.request("config.apply", { config: invalid });
    assert.ok(!response.ok);
    assert.deepEqual(response.error.paths, expected);
    const path = join(h.dir, "bad-config.json");
    writeFileSync(path, JSON.stringify(invalid));
    assert.throws(() => loadConfig(path), (error: unknown) => {
      assert.ok(error instanceof DaemonError);
      assert.deepEqual(error.paths, expected);
      assert.ok(!JSON.stringify(publicError(error)).includes("private-"));
      return true;
    });
    assert.ok(!JSON.stringify(response).includes("private-"));
    assert.throws(() => mergeConfig(h.daemon.config, { retry: {} }), (error: unknown) => {
      assert.ok(error instanceof DaemonError);
      assert.deepEqual(error.paths, ["/retry/enabled"]);
      return true;
    });
    assert.throws(() => mergeConfig(h.daemon.config, { providers: Array(2).fill(h.daemon.config.providers[0]) }),
