const MSI_MAGIC: &str = "d0cf11e0a1b11ae1";
/// zip 文件头魔数 (`PK\x03\x04`) —— uv 的 release 包。
const ZIP_MAGIC: &str = "504b0304";
/// gzip 文件头魔数 (`\x1f\x8b`) —— npm 平台包 tgz (Claude Code)。
const GZ_MAGIC: &str = "1f8b";

