    #[cfg(windows)]
    {
        "irm https://claude.ai/install.ps1 | iex".to_string()
    }
    #[cfg(not(windows))]
    {
        "curl -fsSL https://claude.ai/install.sh | bash".to_string()
    }
}

/// Windows **免管理员**装 Claude Code: 直接抓 npm 平台包 tgz, 解压出 `claude.exe` 到
